// El token se lee del entorno (.env) y viaja SOLO en el encabezado: no queda en ningun archivo.
const url = env.get('INFLUX_URL'), org = env.get('INFLUX_ORG'),
      bucket = env.get('INFLUX_BUCKET'), token = env.get('INFLUX_TOKEN');
if (!url || !org || !bucket || !token) {
    node.error('Faltan variables INFLUX_* en el entorno');
    return null;
}
const ahora = Date.now();   // milisegundos
msg.method = 'POST';
msg.url = url + '/api/v2/write?org=' + encodeURIComponent(org) +
          '&bucket=' + encodeURIComponent(bucket) + '&precision=ms';
msg.headers = { 'Authorization': 'Token ' + token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'prueba_conexion,origen=nodered valor=1.5,contador=1i ' + ahora;
